202	     *
203	     * @param city the city of the new owner
204	     * @return the assigned customer code
205	     */
206	    private String nextCustomerCode(String city) {
207	        long ownersInCity = this.clinicService.findAllOwners().stream()
208	            .filter(existing -> Objects.equals(
209	                normalize(existing.getCity()), normalize(city)))
210	            .count();
211	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
