214	    /**
215	     * Determines whether the given telephone number is already used by any other owner.
216	     *
217	     * @param owner the candidate owner
218	     * @return {@code true} if an owner with the same telephone number already exists in the data store
219	     */
220	    private boolean isDuplicateOwner(Owner owner) {
221	        return this.clinicService.findAllOwners().stream()
222	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
223	    }
224	
225	    /**
226	     * Determines whether the given email address is already used by any other owner. An owner
227	     * without an email address is never considered a duplicate on this criterion. Email addresses
228	     * are compared using {@link #normalize(String)} so the check ignores letter case and any
229	     * surrounding or repeated whitespace.
230	     *
231	     * @param owner the candidate owner
232	     * @return {@code true} if the owner provides an email already used by an existing owner
233	     */
234	    private boolean isDuplicateEmail(Owner owner) {
235	        String email = normalize(owner.getEmail());
236	        if (email.isEmpty()) {
237	            return false;
238	        }
239	        return this.clinicService.findAllOwners().stream()
240	            .anyMatch(existing -> email.equals(normalize(existing.getEmail())));
241	    }
242	
243	    /**
244	     * Normalizes free-form text for duplicate detection so that comparisons ignore letter case and
245	     * surrounding or repeated whitespace: the value is trimmed, runs of internal whitespace are
246	     * collapsed to a single space and the result is lower-cased. This is what makes
247	     * {@code "  john   smith "} and {@code "John Smith"} count as the same value when detecting
248	     * duplicates. A {@code null} value normalizes to the empty string.
249	     *
250	     * @param value the raw value, may be {@code null}
251	     * @return the normalized value, never {@code null}
252	     */
253	    private static String normalize(String value) {
254	        if (value == null) {
255	            return "";
256	        }
257	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
258	    }
